python3 << 'PYEOF'
import json, os

for root, dirs, files in os.walk('.'):
    if 'node_modules' in root or '.build' in root:
        continue
    dirs[:] = [d for d in dirs if d != 'node_modules' and d != '.build']
    if 'package.json' in files:
        path = os.path.join(root, 'package.json')
        try:
            with open(path) as f:
                data = json.load(f)
        except:
            continue

        scripts = data.get('scripts', {})
        tc = scripts.get('type-check', '')
        if tc and 'tsc' in tc:
            print(f'{path}: {repr(tc)}')
PYEOF

